#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct {
    long long key;
    int value;
    char used;
} Entry;

static unsigned long long hash_key(long long x) {
    unsigned long long z = (unsigned long long)x;
    z ^= z >> 33;
    z *= 0xff51afd7ed558ccdULL;
    z ^= z >> 33;
    z *= 0xc4ceb9fe1a85ec53ULL;
    z ^= z >> 33;
    return z;
}

bool checkSubarraySum(int* nums, int numsSize, int k) {
    int cap = 1;
    while (cap < numsSize * 2 + 1) cap <<= 1;

    Entry* table = (Entry*)calloc((size_t)cap, sizeof(Entry));
    if (!table) return false;

    int mask = cap - 1;
    unsigned long long h0 = hash_key(0) & (unsigned)mask;
    table[h0].used = 1;
    table[h0].key = 0;
    table[h0].value = -1;

    long long prefix = 0;
    for (int i = 0; i < numsSize; ++i) {
        prefix = (prefix + nums[i]) % k;

        int pos = (int)(hash_key(prefix) & (unsigned)mask);
        while (table[pos].used && table[pos].key != prefix) {
            pos = (pos + 1) & mask;
        }

        if (table[pos].used) {
            if (i - table[pos].value >= 2) {
                free(table);
                return true;
            }
        } else {
            table[pos].used = 1;
            table[pos].key = prefix;
            table[pos].value = i;
        }
    }

    free(table);
    return false;
}

