        first.put(0L, -1);
        long prefix = 0;

        for (int i = 0; i < nums.length; i++) {
            prefix = (prefix + nums[i]) % k;
            if (first.containsKey(prefix)) {
                if (i - first.get(prefix) >= 2) return true;
            } else {
                first.put(prefix, i);
            }
        }
        return false;
    }
}

